// Return a + b.
int add(int a, int b) {
    return a + b;
}

// Return x squared.
long long square(long long x) {
    return x * x;
}

// True if n is even.
bool is_even(int n) {
    return n % 2 == 0;
}

// Largest element of a non-empty vector.
int max_of(const vector<int>& v) {
    return *max_element(v.begin(), v.end());
}

// Sum of all elements.
long long sum_vec(const vector<int>& v) {
    long long s = 0; for (int x : v) s += x; return s;
}

// Return s reversed.
string reverse_str(const string& s) {
    return string(s.rbegin(), s.rend());
}

// Occurrences of c in s.
int count_char(const string& s, char c) {
    return (int)count(s.begin(), s.end(), c);
}

// n! for n >= 0.
long long factorial(int n) {
    long long r = 1; for (int i = 2; i <= n; ++i) r *= i; return r;
}

// n-th Fibonacci number, fib(0)=0, fib(1)=1.
long long fib(int n) {
    long long a = 0, b = 1; for (int i = 0; i < n; ++i) { long long t = a + b; a = b; b = t; } return a;
}

// True if s reads the same backwards.
bool is_palindrome(const string& s) {
    return equal(s.begin(), s.end(), s.rbegin());
}

// Greatest common divisor (non-negative inputs).
int gcd_of(int a, int b) {
    while (b) { int t = a % b; a = b; b = t; } return a;
}

// True if n is prime.
bool is_prime(int n) {
    if (n < 2) return false; for (int i = 2; (long long)i * i <= n; ++i) if (n % i == 0) return false; return true;
}

// Count vowels (aeiou, case-insensitive).
int count_vowels(const string& s) {
    int c = 0; for (char ch : s) { char l = tolower(ch); if (string("aeiou").find(l) != string::npos) ++c; } return c;
}

// Remove duplicates keeping first occurrences in order.
vector<int> dedupe(const vector<int>& v) {
    vector<int> out; set<int> seen; for (int x : v) if (seen.insert(x).second) out.push_back(x); return out;
}

// Even elements in order.
vector<int> filter_even(const vector<int>& v) {
    vector<int> o; for (int x : v) if (x % 2 == 0) o.push_back(x); return o;
}

// Number of whitespace-separated words.
int word_count(const string& s) {
    istringstream in(s); string w; int n = 0; while (in >> w) ++n; return n;
}

// Uppercase ASCII letters of s.
string to_upper(string s) {
    for (char& c : s) c = toupper(c); return s;
}

// Clamp x into [lo, hi].
int clamp_int(int x, int lo, int hi) {
    return max(lo, min(hi, x));
}

// Binary representation without leading zeros ('0' for 0).
string binary_str(unsigned n) {
    if (n == 0) return "0"; string s; while (n) { s.push_back('0' + (n & 1)); n >>= 1; } reverse(s.begin(), s.end()); return s;
}

// True if non-decreasing.
bool is_sorted_vec(const vector<int>& v) {
    return is_sorted(v.begin(), v.end());
}

// Second largest distinct value (at least two distinct values).
int second_largest(vector<int> v) {
    sort(v.begin(), v.end()); v.erase(unique(v.begin(), v.end()), v.end()); return v[v.size() - 2];
}

// Prefix sums.
vector<long long> running_sum(const vector<int>& v) {
    vector<long long> o; long long t = 0; for (int x : v) { t += x; o.push_back(t); } return o;
}

// True if n is a positive power of two.
bool power_of_two(long long n) {
    return n > 0 && (n & (n - 1)) == 0;
}

// Map each character to its count.
map<char, int> char_freq(const string& s) {
    map<char, int> m; for (char c : s) ++m[c]; return m;
}

// Transpose a non-empty rectangular matrix.
vector<vector<int>> transpose(const vector<vector<int>>& m) {
    vector<vector<int>> t(m[0].size(), vector<int>(m.size())); for (size_t i = 0; i < m.size(); ++i) for (size_t j = 0; j < m[0].size(); ++j) t[j][i] = m[i][j]; return t;
}

// True if two different positions sum to target.
bool pair_sum(const vector<int>& v, int target) {
    unordered_set<int> s; for (int x : v) { if (s.count(target - x)) return true; s.insert(x); } return false;
}

// Lowercase CSS hex color like #ff0000.
string hex_color(int r, int g, int b) {
    char buf[8]; snprintf(buf, sizeof buf, "#%02x%02x%02x", r, g, b); return buf;
}

// Rotate left by k positions.
vector<int> rotate_left(vector<int> v, int k) {
    if (v.empty()) return v; k %= (int)v.size(); rotate(v.begin(), v.begin() + k, v.end()); return v;
}
